import React from 'react';
import { FiPlus, FiCopy, FiCalendar, FiClock } from 'react-icons/fi';
import { toast } from 'react-hot-toast';

const QuickActions = ({ onAddTask, onDuplicateItem, tasks, goals, events, darkMode, setDarkMode }) => {
  const addTodayTask = () => {
    const today = new Date().toISOString().split('T')[0];
    const newTask = {
      task: '',
      date: today,
      time: '09:00',
      priority: 'Medium',
      category: 'Personal',
      notes: ''
    };
    onAddTask(newTask);
    toast.success('Quick task added for today!');
  };

  const duplicateLastItem = () => {
    const lastTask = tasks[tasks.length - 1];
    const lastGoal = goals[goals.length - 1];
    const lastEvent = events[events.length - 1];

    // Find most recent item
    let mostRecent = null;
    let type = '';

    if (lastTask) {
      mostRecent = lastTask;
      type = 'task';
    }
    if (lastGoal && (!mostRecent || lastGoal.id > mostRecent.id)) {
      mostRecent = lastGoal;
      type = 'goal';
    }
    if (lastEvent && (!mostRecent || lastEvent.id > mostRecent.id)) {
      mostRecent = lastEvent;
      type = 'event';
    }

    if (mostRecent) {
      onDuplicateItem(type, mostRecent);
      toast.success(`Duplicated last ${type}!`);
    } else {
      toast.error('No items to duplicate');
    }
  };

  return (
    <div style={{
      position: 'fixed',
      bottom: '20px',
      right: '20px',
      display: 'flex',
      flexDirection: 'column',
      gap: '0.5rem',
      zIndex: 999
    }}>
      <button
        onClick={addTodayTask}
        className="btn btn-primary"
        style={{
          borderRadius: '50%',
          width: '50px',
          height: '50px',
          padding: '0',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
        }}
        title="Add task for today"
      >
        <FiCalendar />
      </button>

      <button
        onClick={duplicateLastItem}
        className="btn btn-secondary"
        style={{
          borderRadius: '50%',
          width: '50px',
          height: '50px',
          padding: '0',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
        }}
        title="Duplicate last item"
      >
        <FiCopy />
      </button>

      <button
        onClick={() => setDarkMode(!darkMode)}
        className="btn btn-secondary"
        style={{
          borderRadius: '50%',
          width: '50px',
          height: '50px',
          padding: '0',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
        }}
        title="Toggle dark mode"
      >
        {darkMode ? '☀️' : '🌙'}
      </button>
    </div>
  );
};

export default QuickActions;
